<?php

declare(strict_types=1);

namespace App\Entities;

use InvalidArgumentException;

/**
 * A persisted task. The identifier is generated by the database, so a Task
 * object always represents an existing row.
 */
final class Task
{
    public const TITLE_MAX_LENGTH = 255;
    public const DESCRIPTION_MAX_LENGTH = 2000;

    public function __construct(
        private readonly int $id,
        private readonly string $title,
        private readonly ?string $description,
        private readonly TaskStatus $status,
    ) {
        if ($id < 1) {
            throw new InvalidArgumentException('A task identifier must be a positive integer.');
        }
    }

    public function id(): int
    {
        return $this->id;
    }

    public function title(): string
    {
        return $this->title;
    }

    public function description(): ?string
    {
        return $this->description;
    }

    public function status(): TaskStatus
    {
        return $this->status;
    }

    /**
     * @return array{id: int, title: string, description: ?string, status: string}
     */
    public function toArray(): array
    {
        return [
            'id' => $this->id,
            'title' => $this->title,
            'description' => $this->description,
            'status' => $this->status->value,
        ];
    }
}
